#include <vector>
#include <array>
#include <cstddef>
#include <omp.h>

void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    bins.fill(0);

    #pragma omp parallel
    {
        std::array<size_t, 10> local_bins{};
        local_bins.fill(0);

        #pragma omp for nowait
        for (std::size_t i = 0; i < x.size(); ++i) {
            double v = x[i];
            int bin = static_cast<int>(v / 10.0);

            // Values are specified to be in [0, 100]. Clamp 100 into the last bin.
            if (bin < 0) {
                bin = 0;
            } else if (bin >= 10) {
                bin = 9;
            }

            ++local_bins[static_cast<std::size_t>(bin)];
        }

        #pragma omp critical
        {
            for (std::size_t b = 0; b < 10; ++b) {
                bins[b] += local_bins[b];
            }
        }
    }
}
